import os


class Config:
    # ==========================================
    # Directories and Paths
    # ==========================================
    # Root directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_11")
    SUBMISSION_DIR = "./submission"

    # Input Files (Generated by metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(
        METADATA_DIR, "val.csv"
    )  # Available but we use full train + CV
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Output Files
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure directories exist
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # ==========================================
    # Global Settings
    # ==========================================
    SEED = 42
    N_FOLDS = 5
    ID_COL = "Id"
    TARGET_COL = "Cover_Type"

    # ==========================================
    # Model Hyperparameters (XGBoost)
    # ==========================================
    # Configuration for Homogeneous Ensemble of XGBoost Classifiers
    # Using 'hist' on 'cuda' for maximum efficiency on A100
    XGB_PARAMS = {
        "objective": "multi:softprob",  # Output probabilities for soft voting
        "eval_metric": "mlogloss",  # Log Loss for early stopping optimization
        "tree_method": "hist",  # GPU-accelerated histogram method
        "device": "cuda",  # Use NVIDIA A100
        "max_depth": 10,  # High capacity as per strategy (Cite Lesson 00014)
        "learning_rate": 0.05,  # eta
        "n_estimators": 3000,  # High cap, controlled by early stopping
        "subsample": 0.8,  # Bagging fraction
        "colsample_bytree": 0.8,  # Feature subsampling
        "random_state": SEED,
        "n_jobs": -1,  # Use all CPU cores for pre-processing steps
        # 'num_class' will be set dynamically based on data
    }

    EARLY_STOPPING_ROUNDS = 100
    VERBOSE_EVAL = 100

    # ==========================================
    # Feature Engineering Configuration
    # ==========================================
    # Flags to control the pipeline
    ENABLE_GEOMETRIC_FEATURES = True
    ENABLE_TARGET_ENCODING = (
        False  # Cite Lesson 00024: Target Encoding degraded performance
    )

    # Column Definitions
    # Continuous/Physical features
    NUMERICAL_FEATURES = [
        "Elevation",
        "Aspect",
        "Slope",
        "Horizontal_Distance_To_Hydrology",
        "Vertical_Distance_To_Hydrology",
        "Horizontal_Distance_To_Roadways",
        "Hillshade_9am",
        "Hillshade_Noon",
        "Hillshade_3pm",
        "Horizontal_Distance_To_Fire_Points",
    ]

    # Categorical Prefixes for One-Hot columns in raw data
    # These will be used to reconstruct dense indices for Target Encoding
    CATEGORICAL_PREFIXES = ["Wilderness_Area", "Soil_Type"]

    # Derived Geometric Feature Names (for reference)
    GEOMETRIC_NEW_FEATURES = [
        "Euclidean_Distance_To_Hydrology",
        "Elevation_Minus_VDH",
        "Aspect_Sin",
        "Aspect_Cos",
    ]

    @classmethod
    def get_all_original_features(cls):
        """
        Returns the list of all 54 original features expected in the dataset.
        Constructs the list dynamically to avoid hardcoding 40 Soil_Types.
        """
        features = cls.NUMERICAL_FEATURES.copy()

        # Add Wilderness_Area1 to Wilderness_Area4
        for i in range(1, 5):
            features.append(f"Wilderness_Area{i}")

        # Add Soil_Type1 to Soil_Type40
        for i in range(1, 41):
            features.append(f"Soil_Type{i}")

        return features
